#include <stdio.h>

#define N 11

int main(void) {
    int a[N] = {0, 5, 13, 19, 21, 37, 56, 64, 75, 80, 88};
    int n = 10;
    int key = 64;
    int i;
    int found;
    const char *res;
    double asl_succ;
    a[0] = key;
    i = n;
    while (a[i] != key) { i--; }
    int cmp = n - i + 1;
    found = (i >= 1) ? 1 : 0;
    res = found ? "是" : "否";
    asl_succ = (double)(n + 1) / 2.0;
    printf("顺序查找（哨兵法）  n=%d  key=%d\n", n, key);
    printf("比较次数（含命中那次）=%d  命中数组下标 i=%d  找到=%s\n", cmp, i, res);
    printf("理论 ASL(成功)=(n+1)/2=%.1f  ASL(失败)=n+1=%d\n", asl_succ, n + 1);
    return 0;
}
